      gl.uniform3fv(gl.getUniformLocation(prog, "uAxisY"), basis.y);
      gl.uniform3fv(gl.getUniformLocation(prog, "uAxisZ"), basis.z);
      gl.viewport(0, 0, faceSize, faceSize);
      gl.drawArrays(gl.TRIANGLES, 0, 3);

